package com.veniux.companion;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.Toast;import org.json.*;import javax.net.ssl.HttpsURLConnection;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
final class MobileUpdater {
 private final Activity activity;private final Handler handler=new Handler(Looper.getMainLooper());private volatile boolean busy=false,closed=false;private long lastCheck=0;private File pending;
 MobileUpdater(Activity activity){this.activity=activity;}
 private HttpsURLConnection connection(String name)throws Exception{if(!name.matches("(?:android\\.json|Veniux-[A-Za-z0-9._-]+\\.apk)"))throw new Exception();HttpsURLConnection c=(HttpsURLConnection)new URL("https://api.veniux.com/updates/files/"+name).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(60000);if(c.getResponseCode()!=200){c.disconnect();throw new Exception();}return c;}
 void resume(){if(closed)return;if(pending!=null){File f=pending;pending=null;install(f);}else check();}
 private void check(){if(busy||lastCheck!=0&&SystemClock.elapsedRealtime()-lastCheck<300000)return;busy=true;lastCheck=SystemClock.elapsedRealtime();new Thread(()->{try{HttpsURLConnection c=connection("android.json");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>65536)throw new Exception();out.write(b,0,n);}}finally{c.disconnect();}JSONObject m=new JSONObject(out.toString("UTF-8"));PackageInfo installed=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0);if(m.getInt("versionCode")>installed.versionCode)handler.post(()->{if(!closed&&!activity.isFinishing())new AlertDialog.Builder(activity).setTitle("Veniux güncellemesi").setMessage("Yeni sürüm hazır: "+m.optString("version")+". İndirdikten sonra Android kurulumunu onaylayın. Hesabınız ve bağlantınız korunur.").setPositiveButton("İndir ve güncelle",(d,w)->download(m)).setNegativeButton("Daha sonra",null).show();});}catch(Exception ignored){}finally{busy=false;if(!closed)handler.postDelayed(this::check,300000);}},"Veniux-update-check").start();}
 private void download(JSONObject m){if(busy)return;busy=true;ProgressDialog progress=new ProgressDialog(activity);progress.setMessage("Güncelleme indiriliyor…");progress.setCancelable(false);progress.show();new Thread(()->{File next=new File(activity.getCacheDir(),"update.next"),file=new File(activity.getCacheDir(),"update.apk");try{
  long expected=m.getLong("bytes");if(expected<=0||expected>500*1048576L||!m.getString("sha256").matches("[a-f0-9]{64}"))throw new Exception();MessageDigest digest=MessageDigest.getInstance("SHA-256");long count=0;HttpsURLConnection c=connection(m.getString("filename"));try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(next)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){count+=n;if(count>expected)throw new Exception();out.write(b,0,n);digest.update(b,0,n);}}finally{c.disconnect();}StringBuilder hash=new StringBuilder();for(byte b:digest.digest())hash.append(String.format(Locale.ROOT,"%02x",b&255));if(count!=expected||!hash.toString().equals(m.getString("sha256")))throw new Exception();
  PackageManager pm=activity.getPackageManager();PackageInfo archive=pm.getPackageArchiveInfo(next.getAbsolutePath(),PackageManager.GET_SIGNATURES),current=pm.getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNATURES);if(archive==null||!archive.packageName.equals(current.packageName)||archive.versionCode!=m.getInt("versionCode")||archive.versionCode<=current.versionCode||!Arrays.equals(archive.signatures,current.signatures))throw new Exception();if(file.exists()&&!file.delete())throw new Exception();if(!next.renameTo(file))throw new Exception();handler.post(()->{if(!closed){progress.dismiss();install(file);}});
 }catch(Exception e){next.delete();handler.post(()->{if(!closed){progress.dismiss();Toast.makeText(activity,"Güncelleme indirilemedi veya doğrulanamadı. Daha sonra tekrar deneyin.",Toast.LENGTH_LONG).show();}});}finally{busy=false;}},"Veniux-update-download").start();}
 private void install(File file){if(closed)return;if(!activity.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(activity).setTitle("Kurulum izni gerekli").setMessage("Veniux güncellemesini kurmak için bu uygulamaya kurulum izni verin. Sonraki ekranda kurulumu onaylayın.").setPositiveButton("İzni aç",(d,w)->{pending=file;activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));}).setNegativeButton("Daha sonra",null).show();return;}Intent intent=new Intent(Intent.ACTION_VIEW);intent.setDataAndType(Uri.parse("content://"+activity.getPackageName()+".updates/update.apk"),"application/vnd.android.package-archive");intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{activity.startActivity(intent);}catch(Exception e){Toast.makeText(activity,"Android kurulum ekranı açılamadı.",Toast.LENGTH_LONG).show();}}
 void close(){closed=true;handler.removeCallbacksAndMessages(null);}
}
